/* Rail/panel ids differ from the canvas section ids they drive. Resolve that here instead of
   patching Document.prototype, so a lookup means the same thing to every caller and to any
   library sharing the page. Order matches the patch it replaces: real id first, alias second. */
export const ID_ALIASES = { repairs: 'solutions', trust: 'trust-bar', 'final-cta': 'cta' };

export function byId(id) {
    if (id == null) return null;
    const found = document.getElementById(id);
    if (found) return found;
    const alias = ID_ALIASES[id];
    return alias ? document.getElementById(alias) : null;
}

