let activeCanvasNode = null;
let activeTargetContext = { type: 'section', node: null };

const SEC_NAMES = {
    header: 'Header',
    hero: 'Hero',
    services: 'Services',
    repairs: 'Solutions',
    about: 'About',
    trust: 'Trust',
    reviews: 'Reviews',
    quote: 'Quote',
    faq: 'FAQ',
    promo: 'Promo',
    contact: 'Contact',
    'final-cta': 'Final CTA',
    footer: 'Footer',
    cookie: 'Cookie Banner'
};

export function normalizeSecId(id) {
    if (!id) return '';
    const map = {
        solutions: 'repairs',
        'trust-bar': 'trust',
        cta: 'final-cta',
        cookieBanner: 'cookie'
    };
    return map[id] || id;
}

