                const v = vars(s); Object.entries(v.vars).forEach(([k, x]) => sec.style.setProperty(k, x)); const dark = v.dark;
                sec.classList.toggle('is-darkbg', dark);
                const row = document.querySelector(`.more-row[data-sec="${id}"]`);
                if (row) row.classList.toggle('is-off', s.show === 'off');
                row.classList.toggle('is-brand', s.scheme === 'brand');
                row.querySelectorAll('[data-more]').forEach(b => b.classList.toggle('active', s[b.dataset.more] === b.dataset.v));
                const shade = row.querySelector('.more-shade');
                shade.value = s.shade;
