            function applyLive(k) {                                   // update the card on the page without re-drawing it
                claims.classList.add('is-editing'); clearTimeout(editT); editT = setTimeout(() => claims.classList.remove('is-editing'), 500);
                const im = card(k) && card(k).querySelector('.ic-img img'); const m = S[k]; if (!im) return;
                im.style.setProperty('--z', m.zoom / 100); im.style.objectPosition = `${m.x}% ${m.y}%`; im.style.transformOrigin = `${m.x}% ${m.y}%`; im.alt = m.alt || '';
            }
