                if (!own) { ready = false; if (dev !== 'desktop') { pendingJump = previewSel(); frame.srcdoc = docHTML('Preview', activePageId()); } return; }   // self-repair
                ready = true; guard(frame.contentDocument); relayout(frame.contentDocument); wireCookie(frame.contentDocument); applyPreviewScroll(frame.contentDocument);
                markActiveNav(frame.contentDocument, frame.contentDocument.body.dataset.previewPage || activePageId());
